// `pnpm --filter @ice/ground gen:shaders` regenerates it; `gen:check` fails the gate when it is stale.
// The .wgsl files are the source: the Node oracle reads them from disk and composes byte-identical text.
export const WGSL = {
  "card/card-pass.wgsl": "// PASS 3 — the card frames, instanced. One quad per card, expanded on the CPU\n// side of the vertex stage by the visual reach (shadow + AA), one distance\n// evaluation per covered fragment in CARD units, premultiplied output.\n\n@group(0) @binding(0) var<uniform> u: FrameUniforms;\n@group(0) @binding(1) var<storage, read> frames: array<Frame>;\n@group(0) @binding(2) var pages: texture_2d_array<f32>;   // the atlas: layers of one size, one binding for every dom card\n@group(0) @binding(3) var samp: sampler;                   // linear, clamp-to-edge\n@group(1) @binding(0) var own: texture_2d<f32>;            // the run's own texture (a 1×1 transparent dummy when none)\n\nstruct VSOut {\n  @builtin(position) clip: vec4f,\n  @location(0) @interpolate(flat) idx: u32,\n}\n\nconst CORNERS = array<vec2f, 6>(\n  vec2f(-1.0, -1.0), vec2f(1.0, -1.0), vec2f(1.0, 1.0),\n  vec2f(-1.0, -1.0), vec2f(1.0, 1.0), vec2f(-1.0, 1.0),\n);\n\nfn px_scale(u: FrameUniforms) -> f32 { return 1.0 / (max(u.cam.z, 1e-12) * max(u.cam.w, 1.0)); }\n\n@vertex\nfn vs(@builtin(vertex_index) vid: u32, @builtin(instance_index) iid: u32) -> VSOut {\n  var out: VSOut;\n  out.clip = vec4f(2.0, 2.0, 2.0, 1.0);   // degenerate: culled instances collapse\n  out.idx = iid;\n  let G = frames[iid];\n  let zoom = max(u.cam.z, 1e-12);\n  // Everything the fragment can paint outside the outer box, in world units.\n  // 2.5σ: the Gaussian tail past it is 0.6% of the shadow's alpha — under 0.4/255 at the\n  // §5 alphas, below the swap chain's resolution and the fragment discard threshold.\n  let pad = G.shadowSigma * 2.5 + G.shadowOffset + 3.0 * px_scale(u);\n  let ext = G.half + vec2f(pad);\n  let lo = (G.centre - ext - u.cam.xy) * zoom;   // CSS px\n  let hi = (G.centre + ext - u.cam.xy) * zoom;\n  if (hi.x < u.box.x || hi.y < u.box.y || lo.x > u.box.x + u.box.z || lo.y > u.box.y + u.box.w) { return out; }   // the slot's box (PORTAL.md §2.3)\n  let corner = CORNERS[vid];\n  let pos = mix(lo, hi, corner * 0.5 + 0.5);\n  out.clip = vec4f(pos.x / u.view.x * 2.0 - 1.0, 1.0 - pos.y / u.view.y * 2.0, 0.0, 1.0);\n  return out;\n}\n\n@fragment\nfn fs(in: VSOut) -> @location(0) vec4f {\n  let G = frames[in.idx];\n  let px = px_scale(u);\n  let p = in.clip.xy * px + u.cam.xy;   // device px → world (card) units\n  let c = shade_frame(G, u, p, px, pages, own, samp);\n  if (c.a < 0.002) { discard; }\n  // Premultiplied: the presentation's opacity through the portal clip scales every channel.\n  let dpr = max(u.cam.w, 1.0);\n  return c * (u.view.w * portal_cover(in.clip.xy / dpr, u.portals, u.clips, dpr));\n}\n",
  "card/card.wgsl": "// The card pass's ENGINE half (design-014): the coverage filter, the analytic\n// shadow blur, the content term (plate · page · own · hole), the premultiplied\n// layer helpers, and the SEAM COMPOSITE — one function, `shade_frame`, that\n// every card program draws through. A program (card/program.ts) provides the\n// two functions declared here and nothing else on the GPU:\n//\n//   shade_card(G, u, p, px) -> Shade   BELOW the content: whatever paints under\n//                                      the card (the shadow) as `under`, the\n//                                      chrome band's colour and coverage `cF`,\n//                                      the interior coverage `cI`, the outer\n//                                      and inner distances, and `skip` when\n//                                      the fragment is past the card's reach.\n//   shade_over(G, u, p, px, s, acc)    ABOVE the content: lines, lights,\n//                                      controls, painted over `acc`.\n//\n// The law the composite keeps: frame and content are ADDITIVE, not\n// sequential. Their coverages partition the pixel (cF + cI == 1 across the\n// shared boundary), and a second `over` would leak bg·cF·cI at the seam. A\n// program returns cF and cI so that they do; the engine composes the one\n// layer. This file names no colour: every rgb is a uniform or the record's.\n\nstruct Shade {\n  under: vec4f,     // premultiplied layers beneath the card (the §5 shadow)\n  chrome: vec3f,    // the frame band's colour at cF\n  cF: f32,          // the band's coverage\n  cI: f32,          // the interior's coverage — the content term paints at it\n  dO: f32,          // signed distance to the outer silhouette (card units)\n  dI: f32,          // signed distance to the inner boundary\n  skip: bool,       // past the card's reach: `under` is the whole answer\n}\n\n// ---- coverage: an exact 1-px box filter. `px` is world units per device pixel.\nfn cov(d: f32, px: f32) -> f32 { return clamp(0.5 - d / px, 0.0, 1.0); }\n\n// The band −w < d < 0: a line of width w just INSIDE a boundary, antialiased\n// on both edges. This is how the hairline and the selection ring are drawn.\nfn inside_line(d: f32, w: f32, px: f32) -> f32 { return cov(d, px) - cov(d + w, px); }\n\nfn erf_approx(x: f32) -> f32 {\n  let s = sign(x);\n  let a = abs(x);\n  let t = 1.0 / (1.0 + 0.3275911 * a);\n  let y = 1.0 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t\n                - 0.284496736) * t + 0.254829592) * t * exp(-a * a);\n  return s * y;\n}\n// Gaussian-blurred coverage — the analytic shadow, straight out of the field.\nfn blur_cov(d: f32, sigma: f32) -> f32 {\n  return 0.5 - 0.5 * erf_approx(d / max(sigma * 1.4142136, 1.0e-4));\n}\n\n// The run's OWN texture is `-srgb` (an island's render target): sampling\n// decoded it to linear and the swap chain is plain, so the write must encode.\n// A pipeline constant, never a uniform flag (README §4c's 1/255 lesson).\noverride ENCODE_SRGB: bool = false;\n\nfn linear_to_srgb(c: vec3f) -> vec3f {\n  return select(1.055 * pow(c, vec3f(1.0 / 2.4)) - 0.055, c * 12.92, c <= vec3f(0.0031308));\n}\n// Defined on UNPREMULTIPLIED colour (design-012 §4): undo the alpha, encode, redo it.\nfn encode_srgb(c: vec4f) -> vec4f {\n  let a = max(c.a, 1e-6);\n  return vec4f(linear_to_srgb(saturate(c.rgb / a)) * a, c.a);\n}\n\n// The CONTENT term (content.ts, design-013 §10.2–10.3): the interior colour at\n// card point `p`. `plate` is the surface colour — today's card. `page` and\n// `own` sample a premultiplied texel and lay it OVER the plate (an island's\n// transparent pixels show the surface): a second `over` INSIDE the content\n// layer, legal — the seam law concerns frame vs content only. The content\n// rect (`chalf`, the inner box) maps onto the WRITTEN rect, clamped half a\n// texel in so the gutter's bilinear safety is exact. `textureSampleLevel`\n// because the branch is per instance and level 0 is the only level a page\n// or a target has.\nfn content_rgb(G: Frame, p: vec2f, pages: texture_2d_array<f32>, own: texture_2d<f32>, samp: sampler) -> vec3f {\n  let plate = G.surface.rgb;\n  if (G.mode == 0u) { return plate; }\n  let dims = select(vec2f(textureDimensions(own)), vec2f(textureDimensions(pages)), G.mode == 1u);\n  let eps = 0.5 / max(G.uv.zw * dims, vec2f(1.0));\n  let t = clamp((p - G.centre) / (2.0 * G.chalf) + vec2f(0.5), eps, vec2f(1.0) - eps);\n  let uv = G.uv.xy + t * G.uv.zw;\n  var c = vec4f(0.0);\n  if (G.mode == 1u) { c = textureSampleLevel(pages, samp, uv, G.layer, 0.0); }\n  else {\n    c = textureSampleLevel(own, samp, uv, 0.0);\n    if (ENCODE_SRGB) { c = encode_srgb(c); }\n  }\n  return c.rgb + plate * (1.0 - c.a);\n}\n\n// Premultiplied \"src over dst\".\nfn over(src: vec4f, dst: vec4f) -> vec4f { return src + dst * (1.0 - src.a); }\n// A straight-alpha colour at coverage c, as a premultiplied layer.\nfn layer(c: vec4f, cov_: f32) -> vec4f { let a = c.a * cov_; return vec4f(c.rgb * a, a); }\n\n// The card, shaded as PREMULTIPLIED layers, bottom to top: the program's\n// `under` · the frame band + the content term as ONE additive layer · the\n// program's `shade_over`. Then the whole card takes its §7 lift opacity,\n// shadow included, exactly as the DOM card's `opacity` does.\nfn shade_frame(G: Frame, u: FrameUniforms, p: vec2f, px: f32, pages: texture_2d_array<f32>, own: texture_2d<f32>, samp: sampler) -> vec4f {\n  let s = shade_card(G, u, p, px);\n  var acc = s.under;\n  // More than a pixel outside the outer box, nothing but what is under the card\n  // can paint — and the shadow skirt is most of the quad, so a program's inner\n  // field is never evaluated for it. Exact, not a heuristic: cov(d, px) is\n  // identically 0 for d ≥ px/2.\n  if (s.skip) { return acc * G.frameAlpha; }\n  // The interior is the content term — a colour today, a texel when the record says so (§10.1) —\n  // or a HOLE (mode 3, PORTAL.md §2.2, §10): the container's inside was drawn beneath through its\n  // FACE (uv.xy the face's centre from the card's, chalf its half extents, uv.z its radius; uv.w\n  // 0 = the whole interior). Inside the face nothing paints — the fill beneath, grown a device px\n  // past this edge, is what shows — and outside it the plate stays: the inset band, the bar. cov()\n  // is the fill's own filter, so at the edge the plate and the hole partition the pixel and\n  // nothing under the container ever shows. (The §5 shadow is outside the silhouette only.)\n  let hole = G.mode == 3u;\n  var content = G.surface.rgb;\n  var cC = s.cI;\n  if (hole) {\n    let covF = select(1.0, cov(sdf_round_box(p - G.centre - G.uv.xy, G.chalf, G.uv.z), px), G.uv.w > 0.5);\n    cC = s.cI * (1.0 - covF);\n  } else if (s.cI > 0.0) { content = content_rgb(G, p, pages, own, samp); }\n  acc = over(vec4f(s.chrome * s.cF + content * cC, s.cF + cC), acc);\n  acc = shade_over(G, u, p, px, s, acc);\n  return acc * G.frameAlpha;\n}\n",
  "card/primitives.wgsl": "// 2D primitives for the card. Pure functions, exact Euclidean distances —\n// which is what everything downstream (1-px AA, the analytic shadow, the\n// hit-test mirror) relies on. Prefixed `sdf_` so this module can share a\n// program with the field module without a name clash.\n// (Lineage: research/sdf-card/src/sdf/primitives.wgsl.)\n\nfn sdf_box(p: vec2f, b: vec2f) -> f32 {\n  let q = abs(p) - b;\n  return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0);\n}\n\nfn sdf_round_box(p: vec2f, b: vec2f, r: f32) -> f32 {\n  let rr = clamp(r, 0.0, min(b.x, b.y));\n  let q  = abs(p) - b + rr;\n  return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0) - rr;\n}\n\nfn sdf_circle(p: vec2f, r: f32) -> f32 { return length(p) - r; }\n\nfn sdf_segment(p: vec2f, a: vec2f, b: vec2f) -> f32 {\n  let pa = p - a;\n  let ba = b - a;\n  let h  = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);\n  return length(pa - ba * h);\n}\n\nfn sdf_rounded_x(p: vec2f, w: f32, r: f32) -> f32 {\n  let q = abs(p);\n  return length(q - min(q.x + q.y, w) * 0.5) - r;\n}\n\n// Exact circular fillet CSG (Quilez). Unlike smin/smax these put a TRUE circle\n// of radius r on the seam. Exact when the operands are perpendicular\n// half-planes — the condition frame.wgsl is built to satisfy.\n//\n// The union form clamps its operands to >= -r so the fillet stays local: the\n// unclamped hg_sdf form keeps growing once both surfaces are more than r\n// inside, and the field goes badly wrong in the interior.\nfn op_union_round(a: f32, b: f32, r: f32) -> f32 {\n  let m = min(a, b);\n  let A = max(a, -r);\n  let B = max(b, -r);\n  let u = max(vec2f(r - A, r - B), vec2f(0.0));\n  return min(m, max(r, min(A, B)) - length(u));\n}\n\nfn op_isect_round(a: f32, b: f32, r: f32) -> f32 {\n  let u = max(vec2f(r + a, r + b), vec2f(0.0));\n  return min(-r, max(a, b)) + length(u);\n}\n",
  "card/shell.wgsl": "// The SHELL — the engine's own card program (design-014): a rounded plate at\n// the card's radius with no chrome band, the §5 ambient shadow, a hairline a\n// pixel inside the edge, and the selection ring that fades in with the\n// reveal — which also carries the drop cue (D2): on the accept tier the ring\n// shows at the heat's presence, so a bare engine still says \"this will take\n// it\". No parts, no lights, no morph. Everything a pack adds, it adds by\n// replacing these two functions (card.wgsl names the contract).\n\nfn shade_card(G: Frame, u: FrameUniforms, p: vec2f, px: f32) -> Shade {\n  var s: Shade;\n  let dO = sdf_round_box(p - G.centre, G.half, G.outerR);\n  var acc = vec4f(0.0);\n  // §5: the outer silhouette, Gaussian-blurred, cast down by `shadowOffset`.\n  // Only outside the card — what the card covers, the card paints.\n  if (G.shadowSigma > 0.01) {\n    let sh = blur_cov(sdf_round_box(p - vec2f(0.0, G.shadowOffset) - G.centre, G.half, G.outerR), G.shadowSigma)\n           * G.shadowAlpha * u.colBg.w * (1.0 - cov(dO, px));\n    acc = over(vec4f(0.0, 0.0, 0.0, sh), acc);\n  }\n  s.under = acc;\n  s.dO = dO;\n  s.dI = dO;                 // no band: the content rect IS the card\n  s.chrome = vec3f(0.0);\n  s.cF = 0.0;\n  s.cI = cov(dO, px);\n  s.skip = dO > px;\n  return s;\n}\n\nfn shade_over(G: Frame, u: FrameUniforms, p: vec2f, px: f32, s: Shade, acc_in: vec4f) -> vec4f {\n  var acc = acc_in;\n  // §2.3 the hairline, 1 px inside the outer edge.\n  acc = over(layer(u.colHair, inside_line(s.dO, u.lines.x, px)), acc);\n  // §7 the sole-selection ring, 1.5 px inside the same edge — and the drop cue at the accept tier (D2).\n  let ring = max(G.ring, G.hot.z * G.hot.w);\n  acc = over(layer(vec4f(u.colRing.rgb, ring), inside_line(s.dO, u.lines.y, px)), acc);\n  return acc;\n}\n",
  "field/atlas-bake.wgsl": "// PASS 1 — the lattice-aligned field atlas.\n//\n// One fragment per lattice site of the finest LIVE rung. Since mid = fine × 10\n// and coarse = fine × 100, a single atlas at that step serves all three rungs\n// exactly. Sized by site count, not by framebuffer. Target: rgba32float, no\n// blending. Re-run when cards or the camera change — never on pointer motion.\n\n@group(0) @binding(0) var<uniform> u: Uniforms;\n@group(0) @binding(1) var<storage, read> cards: array<Card>;\n\nstruct VSOut { @builtin(position) clip: vec4f }\n\n@vertex\nfn vs(@builtin(vertex_index) vid: u32) -> VSOut {\n  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));\n  var out: VSOut;\n  out.clip = vec4f(p[vid], 0.0, 1.0);\n  return out;\n}\n\n@fragment\nfn fs(in: VSOut) -> @location(0) vec4f {\n  let idx = u.atlas.xy + floor(in.clip.xy);\n  let screen = site_screen(u, idx * u.phase.w);\n\n  let k = u.field.x;\n  let eps = u.field.y;\n  let polarity = u.field.z;\n  var field = vec2f(0.0);\n  var min_d = 1e9;\n\n  // The AABB reject must stay a branch: a branchless \"always run the SDF\"\n  // variant measured 3x slower at high card counts.\n  let pad = sqrt(max(k, 1.0) / 0.02);\n  let count = min(u32(u.flags.x + 0.5), arrayLength(&cards));\n  for (var i = 0u; i < count; i++) {\n    let card = cards[i];\n    let center = card.center_half.xy;\n    let half = card.center_half.zw;\n    let radius = card.shape.x;\n    let strength = card.shape.y;\n    let rel = screen - center;\n    let reach = pad * sqrt(max(strength, 0.0001));\n    if (abs(rel.x) > half.x + reach || abs(rel.y) > half.y + reach) { continue; }\n    let d = sd_round_box(rel, half, radius);\n    min_d = min(min_d, d);\n    let dist = max(d, 0.0);\n    let outward = round_box_normal(rel, half, radius);\n    field += -outward * (k * strength * polarity / (dist * dist + eps));\n  }\n  return vec4f(field, min_d, 0.0);\n}\n",
  "field/fine-dot.wgsl": "// PASS 2, dense branch — the FINE rung as one fullscreen triangle, DOT glyph.\n// Above ~40 k on-screen fine sites the vertex stage of the instanced draw costs\n// more than shading every pixel; the host switches this in instead.\n\n@group(0) @binding(0) var<uniform> u: Uniforms;\n@group(0) @binding(1) var atlas_tex: texture_2d<f32>;\n\nstruct VSOut { @builtin(position) clip: vec4f }\n\n@vertex\nfn vs(@builtin(vertex_index) vid: u32) -> VSOut {\n  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));\n  var out: VSOut;\n  out.clip = vec4f(p[vid], 0.0, 1.0);\n  return out;\n}\n\n@fragment\nfn fs(in: VSOut) -> @location(0) vec4f {\n  let screen = in.clip.xy / dpr(u);\n  let spacing = u.rungs.x;\n  let world = u.phase.xy + screen / zoom(u);\n  let idx = round(world / spacing);\n  if (promoted(idx)) { discard; }          // the mid rung owns this site\n\n  let site = site_screen(u, idx * spacing);\n  let cell = max(spacing * zoom(u), 1e-6);\n  let hl = fit_hl(u, cell);\n  let aa = aa_px(u);\n  if (length(screen - site) > dot_radius(u, hl * 1.05) + aa * 2.0) { discard; }\n\n  let packed = field_at_site(u, atlas_tex, atlas_index(u, idx, spacing), site);\n  if (packed.z < -0.5) { discard; }\n\n  let mag = length(packed.xy);\n  let influence = mag / (mag + 1.0);\n  let radius = dot_radius(u, mix(hl * 0.16, hl * 1.05, influence));\n  let a = cover_dot(screen, site, radius, aa) * portal_cover(screen, u.portals, u.clips, dpr(u)) *\n          mix(0.72, 1.0, influence) * rung_alpha(u, 0.0) * u.color.w;\n  if (a < 0.004) { discard; }\n  return vec4f(u.color.xyz, a);\n}\n",
  "field/glyph-dot.wgsl": "// PASS 2 — instanced DOT glyphs. One quad per lattice site; the field is read\n// ONCE per site in the vertex stage. RUNG is a pipeline override — 0 fine,\n// 1 mid, 2 coarse — so this file is three specialised pipelines.\n\noverride RUNG: f32 = 1.0;\n\n@group(0) @binding(0) var<uniform> u: Uniforms;\n@group(0) @binding(1) var atlas_tex: texture_2d<f32>;\n\nstruct VSOut {\n  @builtin(position) clip: vec4f,\n  @location(0) @interpolate(flat) site: vec2f,\n  @location(1) @interpolate(flat) radius: f32,\n  @location(2) @interpolate(flat) alpha: f32,\n}\n\nconst CORNERS = array<vec2f, 6>(\n  vec2f(-1.0, -1.0), vec2f(1.0, -1.0), vec2f(1.0, 1.0),\n  vec2f(-1.0, -1.0), vec2f(1.0, 1.0), vec2f(-1.0, 1.0),\n);\n\n@vertex\nfn vs(@builtin(vertex_index) vid: u32, @builtin(instance_index) iid: u32) -> VSOut {\n  var out: VSOut;\n  out.clip = vec4f(2.0, 2.0, 2.0, 1.0);   // degenerate: culled instances collapse\n  out.site = vec2f(0.0);\n  out.radius = 0.0;\n  out.alpha = 0.0;\n\n  let spacing = rung_spacing(u, RUNG);\n  let cell = max(spacing * zoom(u), 1e-6);\n  let cols = max(u32(select(select(u.cols.x, u.cols.y, RUNG > 0.5), u.cols.z, RUNG > 1.5) + 0.5), 1u);\n  // The slot's box (PORTAL.md §2.3): the instance grid starts at the box's top-left (a root's is 0 — exactly the phase)\n  let origin = floor((u.phase.xy + u.box.xy / zoom(u)) / spacing) - vec2f(1.0);\n  let idx = origin + vec2f(f32(iid % cols), f32(iid / cols));\n\n  if (RUNG < 1.5 && promoted(idx)) { return out; }   // a coarser rung owns this site\n\n  let site = site_screen(u, idx * spacing);\n  let hl = fit_hl(u, cell);\n  let aa = aa_px(u);\n  let extent = dot_radius(u, hl * 1.05) + aa * 2.0;\n  if (site.x < u.box.x - extent || site.y < u.box.y - extent ||\n      site.x > u.box.x + u.box.z + extent || site.y > u.box.y + u.box.w + extent) { return out; }\n\n  let packed = field_at_site(u, atlas_tex, atlas_index(u, idx, spacing), site);\n  if (packed.z < -0.5) { return out; }   // a card covers this site\n\n  let mag = length(packed.xy);\n  let influence = mag / (mag + 1.0);\n  let radius = dot_radius(u, mix(hl * 0.16, hl * 1.05, influence));\n  let alpha = mix(0.72, 1.0, influence) * rung_alpha(u, RUNG) * u.color.w;\n  if (alpha < 0.004) { return out; }\n\n  let corner = CORNERS[vid];\n  let pos = site + corner * (radius + aa * 2.0);\n  out.clip = vec4f(pos.x / u.view.x * 2.0 - 1.0, 1.0 - pos.y / u.view.y * 2.0, 0.0, 1.0);\n  out.site = site;\n  out.radius = radius;\n  out.alpha = alpha;\n  return out;\n}\n\n@fragment\nfn fs(in: VSOut) -> @location(0) vec4f {\n  let screen = in.clip.xy / dpr(u);\n  let a = in.alpha * cover_dot(screen, in.site, in.radius, aa_px(u)) * portal_cover(screen, u.portals, u.clips, dpr(u));\n  if (a < 0.004) { discard; }\n  return vec4f(u.color.xyz, a);\n}\n",
  "field/line-grid.wgsl": "// PASS 2, the LINE grid — the engine's second glyph (design-013 §8, D-C1.4). A\n// SURFACE program (field/program.ts): one fullscreen triangle that draws the\n// lattice's LINES instead of a glyph at each of its sites, so it reads no atlas\n// and the field bake never runs for it. The mechanism is the cutting mat's\n// (packs/mat/mat.wgsl `line_coverage` · `grid2` · `line_weight`) — analytic\n// coverage on the same three rungs, weighted by lattice/line.ts's law over the\n// engine's own fade-in window — without the mat's material, its gobo or its\n// colour chain: the ink is the theme's line ink and the alpha is the field\n// config's, exactly as the dot's is.\n\n@group(0) @binding(0) var<uniform> u: Uniforms;\n@group(0) @binding(1) var<uniform> lg: LineUniforms;\n\nstruct VSOut { @builtin(position) clip: vec4f }\n\n@vertex\nfn vs(@builtin(vertex_index) vid: u32) -> VSOut {\n  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));\n  var out: VSOut;\n  out.clip = vec4f(p[vid], 0.0, 1.0);\n  return out;\n}\n\n// Coverage of one rung's lines through a point. `x`, `spacing`, `half_width`\n// and `px` are all WORLD units; `px` is one device pixel, which is both the\n// half-width's unit conversion and the antialiasing window.\nfn line_cover(x: f32, spacing: f32, half_width: f32, px: f32) -> f32 {\n  let d = abs(fract(x / spacing - 0.5) - 0.5) * spacing;\n  return 1.0 - smoothstep(max(half_width - px, 0.0), half_width + px, d);\n}\n\nfn line_grid2(p: vec2f, spacing: f32, half_width: f32, px: f32) -> f32 {\n  return max(line_cover(p.x, spacing, half_width, px), line_cover(p.y, spacing, half_width, px));\n}\n\n// lattice/line.ts `lineWeight`, on the engine's window (`u.lod`) and the config's\n// law: a rung fades in by its OWN cell — the same smoothstep every glyph fades by\n// (magnet.wgsl `rung_alpha`), so a decade wrap is continuous by construction — and\n// then thickens and darkens over the next decade. x = half-width (DEVICE px),\n// y = alpha. The ENGINE's law is flat in both decade terms (theme.ts LINE_GRID):\n// one width and one weight at every rung, which is what the old TSL grid drew.\nfn line_weight(u: Uniforms, law: vec4f, cell_px: f32) -> vec2f {\n  let s = smoothstep(u.lod.x, u.lod.y, cell_px);\n  let t = saturate(log(max(cell_px, 1e-9) / u.lod.y) / 2.302585093);\n  return vec2f(mix(law.x, law.y, t), law.z * s + (law.w - law.z) * t);\n}\n\n// One rung composited into the coverage so far, by max() — a coarser rung's\n// lines sit on a subset of the finer rung's sites, and the stronger weight wins\n// there (the reference's compositing, and `promoted()`'s intent for the dot).\nfn line_rung(u: Uniforms, law: vec4f, world: vec2f, spacing: f32, px: f32, cover: f32) -> f32 {\n  let w = line_weight(u, law, spacing * zoom(u));\n  if (w.y <= 0.0) { return cover; }   // a rung under the window draws nothing, and costs one compare\n  return max(cover, line_grid2(world, spacing, w.x * px, px) * w.y);\n}\n\n@fragment\nfn fs(in: VSOut) -> @location(0) vec4f {\n  let z = zoom(u);\n  let d = dpr(u);\n  let screen = in.clip.xy / d;               // CSS px\n  let px = 1.0 / (z * d);                    // world units per DEVICE px\n  let world = u.phase.xy + screen / z;       // lattice-phase world (the camera is pre-wrapped on the CPU)\n  var cover = line_rung(u, lg.law, world, u.rungs.x, px, 0.0);\n  cover = line_rung(u, lg.law, world, u.rungs.y, px, cover);\n  cover = line_rung(u, lg.law, world, u.rungs.z, px, cover);\n  // `u.color.w` is the field config's ink alpha through the presentation's opacity —\n  // the dot's alpha term, unchanged; only the ink itself is the line grid's own.\n  let a = cover * u.color.w * portal_cover(screen, u.portals, u.clips, d);\n  if (a < 0.004) { discard; }\n  return vec4f(lg.ink.xyz, a);\n}\n",
  "field/magnet.wgsl": "// The magnet-grid maths. A PURE module: no bindings. The uniform block and the\n// atlas texture arrive as parameters, so the entry alone decides the binding\n// layout. `Uniforms` and `Card` are generated from src/field/layout.ts and\n// prepended by the engine before this text.\n//\n// Every function body here is the validated prototype's, unchanged — except\n// that a glyph is one size on every rung (`fit_hl` takes no rung multiplier).\n\nfn sd_round_box(p: vec2f, b: vec2f, r: f32) -> f32 {\n  let rr = min(r, min(b.x, b.y));\n  let q = abs(p) - b + vec2f(rr, rr);\n  return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0) - rr;\n}\n\nfn round_box_normal(p: vec2f, b: vec2f, r: f32) -> vec2f {\n  let s = sign(p);\n  let inner = max(b - vec2f(r, r), vec2f(0.0));\n  let d = abs(p) - inner;\n  if (d.x > 0.0 && d.y > 0.0) {\n    let n = length(d);\n    if (n > 0.0001) { return s * (d / n); }\n    return vec2f(s.x, 0.0);\n  }\n  if (d.x > d.y) { return vec2f(s.x, 0.0); }\n  return vec2f(0.0, s.y);\n}\n\nfn safe_normalize(v: vec2f, fallback: vec2f) -> vec2f {\n  let n = length(v);\n  if (n > 0.0001) { return v / n; }\n  return fallback;\n}\n\nfn zoom(u: Uniforms) -> f32 { return max(u.cam.z, 1e-12); }\nfn dpr(u: Uniforms) -> f32 { return max(u.cam.w, 1.0); }\nfn aa_px(u: Uniforms) -> f32 { return max(0.6 / dpr(u), 0.35); }\nfn rest_dir(u: Uniforms) -> vec2f { return safe_normalize(u.glyph.xy, vec2f(0.0, 1.0)); }\n\n// World -> screen for a lattice site. The camera is pre-wrapped to the coarse\n// period on the CPU so round(world / spacing) stays exact at any zoom.\nfn site_screen(u: Uniforms, site_world: vec2f) -> vec2f {\n  return (site_world - u.phase.xy) * zoom(u);\n}\n\nfn rung_spacing(u: Uniforms, rung: f32) -> f32 {\n  return select(select(u.rungs.x, u.rungs.y, rung > 0.5), u.rungs.z, rung > 1.5);\n}\n\n// One size for every rung; a rung's alpha is smoothstep(fadeIn, its OWN cell\n// in px): the site that is the fine rung at a 20 px cell becomes the mid rung\n// at a 20 px cell with the same size and the same alpha, so a decade wrap\n// cannot pop. (The prototype's size ladder is gone — lod.ts.)\nfn rung_alpha(u: Uniforms, rung: f32) -> f32 {\n  return smoothstep(u.lod.x, u.lod.y, rung_spacing(u, rung) * zoom(u));\n}\n\nfn fit_hl(u: Uniforms, cell_px: f32) -> f32 { return min(u.glyph.z, cell_px * 0.42); }\nfn fit_hw(u: Uniforms, cell_px: f32) -> f32 { return min(u.glyph.w, cell_px * 0.42 * 0.22); }\n\n// The PRESET size ranges (CSS px), applied LAST: whatever the rung multiplier,\n// the cell fit and the field influence made of the base size, the drawn glyph\n// stays inside them. Monotonic, so the clamped maximum is the clamp of the\n// maximum — the entries size their quads and culls with the same calls.\nfn dot_radius(u: Uniforms, r: f32) -> f32 { return clamp(r, u.dotRange.x, u.dotRange.y); }\nfn needle_len(u: Uniforms, l: f32) -> f32 { return clamp(l, u.needleRange.x, u.needleRange.y); }\nfn needle_wid(u: Uniforms, w: f32) -> f32 { return clamp(w, u.needleRange.z, u.needleRange.w); }\n\n// A site whose index is a multiple of ten on both axes also belongs to the next\n// coarser rung, which always draws the larger glyph at the same alpha; letting it\n// own the site reproduces the reference's max() compositing exactly.\nfn promoted(idx: vec2f) -> bool {\n  return abs(idx.x - round(idx.x / 10.0) * 10.0) < 0.5 &&\n         abs(idx.y - round(idx.y / 10.0) * 10.0) < 0.5;\n}\n\nfn cover_dot(screen: vec2f, site: vec2f, radius: f32, aa: f32) -> f32 {\n  return 1.0 - smoothstep(max(radius - aa, 0.0), radius + aa, length(screen - site));\n}\n\nfn cover_needle(screen: vec2f, site: vec2f, dir: vec2f, hl: f32, hw: f32, aa: f32) -> f32 {\n  let rel = screen - site;\n  let nrm = vec2f(-dir.y, dir.x);\n  let local = vec2f(dot(rel, nrm), dot(rel, dir));\n  let across = 1.0 - smoothstep(max(hw - aa, 0.0), hw + aa, abs(local.x));\n  let along = 1.0 - smoothstep(max(hl - aa, 0.0), hl + aa, abs(local.y));\n  return across * along;\n}\n\n// Field at one lattice site: the baked CARD field from the atlas (a textureLoad\n// that lands exactly on the texel written for this site — no filtering) plus\n// the CURSOR, added analytically so pointer motion never invalidates the atlas.\n// The cursor's STRENGTH is `u.flags.z` (design-013 C2, D-C2.2: a host's pointer\n// pole rides this term, strength and all); a plain cursor is 1, and `× 1.0` is\n// the old expression bit for bit.\nfn field_at_site(u: Uniforms, atlas_tex: texture_2d<f32>, atlas_idx: vec2f, screen: vec2f) -> vec3f {\n  var f = vec2f(0.0);\n  if (u.flags.y > 0.5) {\n    let to_pole = u.view.zw - screen;\n    let r2 = dot(to_pole, to_pole) + u.field.y;\n    f += safe_normalize(to_pole, rest_dir(u)) * (u.field.x * u.field.z * u.flags.z / r2);\n  }\n  let t = vec2i(round(atlas_idx - u.atlas.xy));\n  let dims = vec2i(u.atlas.zw);\n  if (t.x < 0 || t.y < 0 || t.x >= dims.x || t.y >= dims.y) {\n    return vec3f(f, 1e9);\n  }\n  let s = textureLoad(atlas_tex, t, 0);\n  return vec3f(f + s.xy, s.z);\n}\n\n// Site index in atlas-step units for a site of the given rung.\nfn atlas_index(u: Uniforms, idx: vec2f, spacing: f32) -> vec2f {\n  return idx * round(spacing / u.phase.w);\n}\n\n// The glyph's rest-vs-field direction, shared by both needle entries.\nfn needle_dir(u: Uniforms, field: vec2f) -> vec2f {\n  let mag = length(field);\n  let influence = clamp(mag, 0.0, 1.0);\n  let fdir = safe_normalize(field, rest_dir(u));\n  if (u.field.w > 0.5) { return fdir; }\n  return safe_normalize(mix(rest_dir(u), fdir, influence), rest_dir(u));\n}\n",
  "overlay/soup.wgsl": "// The overlay SOUP (design-013 §8 C1, D-C1.2) — a triangle list in the slot's\n// SCREEN CSS px with a colour per vertex, drawn into the slot's render pass\n// between the field and the frames (`under`: wires) or after them (`over`:\n// guides). The vertex maps px → clip through the slot's own view; the fragment\n// is the vertex colour, faded by the slot's presentation opacity and clipped by\n// its portal CHAIN, exactly as the field and the fill are — so a slot seen\n// through a face carries its overlays through the same hole.\n//\n// No depth, straight-alpha \"source over\", and `cullMode: \"none\"`: the screen-px\n// collectors emit y-down geometry, which lands CLOCKWISE through this mapping.\n// Under three that needed `DoubleSide` (the invisible-guides find, 2026-07-16);\n// under WebGPU the default is to cull nothing. The pipeline states it anyway and\n// the oracle's `overlay-soup-z1` scene carries a clockwise triangle and a\n// counter-clockwise one, so both windings are asserted to land in real pixels\n// rather than the default being trusted to hold.\n\n@group(0) @binding(0) var<uniform> u: SoupUniforms;\n\nstruct VSOut {\n  @builtin(position) clip  : vec4f,\n  @location(0)       color : vec4f,\n}\n\n@vertex\nfn vs(@location(0) pos: vec3f, @location(1) color: vec4f) -> VSOut {\n  let css = vec2f(max(u.view.x, 1.0), max(u.view.y, 1.0));\n  var out: VSOut;\n  out.clip = vec4f(pos.x / css.x * 2.0 - 1.0, 1.0 - pos.y / css.y * 2.0, 0.0, 1.0);\n  out.color = color;\n  return out;\n}\n\n@fragment\nfn fs(in: VSOut) -> @location(0) vec4f {\n  let dpr = max(u.view.z, 1.0);\n  let a = in.color.a * u.view.w * portal_cover(in.clip.xy / dpr, u.portals, u.clips, dpr);\n  if (a < 0.002) { discard; }\n  return vec4f(in.color.rgb, a);\n}\n",
  "packs/mat/mat-pass.wgsl": "// PASS 2, the cutting mat — one fullscreen triangle: the lattice's lines as\n// analytic coverage, the grain, the gobo projected onto the desk plane, the\n// reference's grade by day or the night's eye by night (MAT.md). Alpha 1 at\n// rest (a plain write); a flight fades it and clips it to the portal.\n\n@group(0) @binding(0) var<uniform> u: MatUniforms;\n@group(0) @binding(1) var gobo_tex: texture_2d<f32>;\n@group(0) @binding(2) var gobo_samp: sampler;\n@group(0) @binding(3) var noise_tex: texture_2d<f32>;\n@group(0) @binding(4) var noise_samp: sampler;\n\nstruct VSOut { @builtin(position) clip: vec4f }\n\n@vertex\nfn vs(@builtin(vertex_index) vid: u32) -> VSOut {\n  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));\n  var out: VSOut;\n  out.clip = vec4f(p[vid], 0.0, 1.0);\n  return out;\n}\n\n@fragment\nfn fs(in: VSOut) -> @location(0) vec4f {\n  let zoom = mat_zoom(u);\n  let dpr = mat_dpr(u);\n  let frag = in.clip.xy;                       // device px\n  let screen = frag / dpr;                     // CSS px\n  let px = 1.0 / (zoom * dpr);                 // world per device px\n  let bn = textureSampleLevel(noise_tex, noise_samp, frag * u.noise.z + u.noise.xy, 0.0).rgb;\n  let albedo = mat_albedo(u, u.phase.xy + screen / zoom, px, frag, bn);\n  let gobo = sample_gobo(u, gobo_tex, gobo_samp, desk_of(u, u.cam.xy + screen / zoom), bn.z);\n  // Straight alpha: the presentation's opacity through the portal clip — both 1 at rest,\n  // when \"source over\" reduces to a plain write.\n  return vec4f(mat_colour(u, albedo, gobo, bn.y), u.view.w * portal_cover(screen, u.portals, u.clips, dpr));\n}\n",
  "packs/mat/mat.wgsl": "// The cutting mat's maths — a PURE module: no bindings. The uniform block and\n// the textures arrive as parameters. Every function body is the reference's\n// (research/tree-shadow/prototype/src/shaders.js), transcribed to the engine's\n// units: world = CSS px at zoom 1, the lattice's decade rungs, `MatUniforms`\n// from src/mat/layout.ts prepended by the engine.\n\nfn mat_zoom(u: MatUniforms) -> f32 { return max(u.cam.z, 1e-12); }\nfn mat_dpr(u: MatUniforms) -> f32 { return max(u.cam.w, 1.0); }\n\n// ---- the reference's noise (hash12 · valueNoise), on framebuffer pixels\nfn hash12(p: vec2f) -> f32 {\n  let n = sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453;\n  return n - floor(n);\n}\n\nfn value_noise(p: vec2f) -> f32 {\n  let i = floor(p);\n  var f = fract(p);\n  f = f * f * (3.0 - 2.0 * f);\n  return mix(\n    mix(hash12(i), hash12(i + vec2f(1.0, 0.0)), f.x),\n    mix(hash12(i + vec2f(0.0, 1.0)), hash12(i + vec2f(1.0, 1.0)), f.x),\n    f.y);\n}\n\nfn srgb_to_linear(c: vec3f) -> vec3f {\n  return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3f(2.4)), step(vec3f(0.04045), c));\n}\n\nfn rgb2hsb(c: vec3f) -> vec3f {\n  let K = vec4f(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);\n  let p = mix(vec4f(c.bg, K.wz), vec4f(c.gb, K.xy), step(c.b, c.g));\n  let q = mix(vec4f(p.xyw, c.r), vec4f(c.r, p.yzx), step(p.x, c.r));\n  let d = q.x - min(q.w, q.y);\n  let e = 1.0e-10;\n  return vec3f(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);\n}\n\nfn hsb2rgb(c: vec3f) -> vec3f {\n  let K = vec4f(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);\n  let p = abs(fract(K.xyz + c.x) * 6.0 - K.w);\n  return c.z * mix(K.xxx, clamp(p - K.x, vec3f(0.0), vec3f(1.0)), c.y);\n}\n\n// ---- the lines. `px` is world units per DEVICE pixel; half-widths are in device px.\nfn line_coverage(x: f32, spacing: f32, half_width: f32, px: f32) -> f32 {\n  let d = abs(fract(x / spacing - 0.5) - 0.5) * spacing;\n  return 1.0 - smoothstep(max(half_width - px, 0.0), half_width + px, d);\n}\n\nfn grid2(p: vec2f, spacing: f32, half_width: f32, px: f32) -> f32 {\n  return max(line_coverage(p.x, spacing, half_width, px), line_coverage(p.y, spacing, half_width, px));\n}\n\n// One law for every rung (src/lattice/line.ts `lineWeight`): fade in over the\n// engine's window by the rung's OWN cell, then thicken and darken over the\n// next decade. x = half-width (device px), y = alpha.\nfn line_weight(u: MatUniforms, cell_px: f32) -> vec2f {\n  let s = smoothstep(u.lod.x, u.lod.y, cell_px);\n  let t = saturate(log(max(cell_px, 1e-9) / u.lod.y) / 2.302585093);\n  return vec2f(mix(u.line.x, u.line.y, t), u.line.z * s + (u.line.w - u.line.z) * t);\n}\n\n// The mat's albedo at a point: the reference's `cuttingMatAlbedo` with the\n// three lattice rungs in place of its own decade, and the line law above in\n// place of its fade ladder. `world` is lattice-phase world (wrapped); `px` is\n// world per device pixel; `frag` is the framebuffer pixel.\nfn mat_albedo(u: MatUniforms, world: vec2f, px: f32, frag: vec2f, bn: vec3f) -> vec3f {\n  var sage = u.ground.xyz;\n  let amp = u.grain.x;\n  var g = (hash12(frag * vec2f(0.73, 0.91)) - 0.5) * amp;\n  g += (value_noise(frag * 0.45 + vec2f(u.view.z * 0.9, -u.view.z * 0.6)) - 0.5) * amp;\n  g += (bn.x - 0.5) * amp * 0.5;\n  sage += vec3f(g * 0.4, g, g * 0.35);\n\n  // A rung under the window has alpha 0 and no coverage to compute — the\n  // fine rung at most zooms. The branches are uniform across the frame.\n  let zoom = mat_zoom(u);\n  var cover = 0.0;\n  let wf = line_weight(u, u.rungs.x * zoom);\n  if (wf.y > 0.0) { cover = grid2(world, u.rungs.x, wf.x * px, px) * wf.y; }\n  let wm = line_weight(u, u.rungs.y * zoom);\n  if (wm.y > 0.0) { cover = max(cover, grid2(world, u.rungs.y, wm.x * px, px) * wm.y); }\n  let wc = line_weight(u, u.rungs.z * zoom);\n  if (wc.y > 0.0) { cover = max(cover, grid2(world, u.rungs.z, wc.x * px, px) * wc.y); }\n  return srgb_to_linear(clamp(mix(sage, u.ink.xyz, cover), vec3f(0.0), vec3f(1.0)));\n}\n\n// ---- the gobo (the reference's sampleBlur · getGoboBlurRatio · sampleGobo)\nfn linearstep(edge0: f32, edge1: f32, x: f32) -> f32 {\n  return clamp((x - edge0) / (edge1 - edge0), 0.0, 1.0);\n}\n\n// Linearise the WebGL-range NDC z with the projector's near/far, then ramp\n// between the two depths: sharp near the projector, soft far from it.\nfn blur_ratio(ndc_z: f32, p: vec4f) -> f32 {\n  return linearstep(p.x, p.y, (2.0 * p.z * p.w) / (p.w + p.z - ndc_z * (p.w - p.z)));\n}\n\n// Six taps on a golden-angle spiral, the start angle from blue noise so the\n// pattern differs per pixel (and per frame while the offset moves).\nfn sample_blur(tex: texture_2d<f32>, samp: sampler, uv: vec2f, texel: vec2f, blur: f32, n: f32) -> f32 {\n  // No blur: six taps at one point are one tap. The sharp end of the desk.\n  if (blur <= 0.0) { return textureSampleLevel(tex, samp, uv, 0.0).r; }\n  let G = 2.39996323;\n  let rot = mat2x2f(cos(G), sin(G), -sin(G), cos(G));\n  let a0 = n * 6.28318530718;\n  var d = vec2f(cos(a0), sin(a0));\n  let s = texel * blur * (1.0 / sqrt(6.0));\n  var c = 0.0;\n  for (var i = 0; i < 6; i++) {\n    c += textureSampleLevel(tex, samp, uv + d * sqrt(f32(i + 1)) * s, 0.0).r;\n    d = rot * d;\n  }\n  return c / 6.0;\n}\n\n// The gobo term at a desk point (metres): 1 = lit. Outside the projector's\n// frame the plate is not consulted at all — the cone is finite, as the\n// reference's is.\nfn sample_gobo(u: MatUniforms, tex: texture_2d<f32>, samp: sampler, desk: vec3f, n: f32) -> f32 {\n  if (u.gobo.x <= 0.0) { return 1.0; }\n  var clip = u.goboMatrix * vec4f(desk, 1.0);\n  let ndc = clip.xyz / clip.w;\n  // The wind target's row 0 is the plate's top row, so v runs downward.\n  let uv = vec2f(0.5 + 0.5 * ndc.x, 0.5 - 0.5 * ndc.y);\n  if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) { return 1.0; }\n  let g = sample_blur(tex, samp, uv, vec2f(1.0 / 512.0), blur_ratio(ndc.z, u.goboParams) * u.gobo.y, n);\n  return mix(1.0, g, u.gobo.x);\n}\n\n// World (CSS px at zoom 1, unwrapped) → the desk plane in the projector's frame.\nfn desk_of(u: MatUniforms, world: vec2f) -> vec3f {\n  return vec3f(u.plane.x + world.x * u.plane.z, u.plane.w, u.plane.y + world.y * u.plane.z);\n}\n\n// The reference's grade: `shade = mix(1, floor + (1 − floor)·gobo, mix)`, then\n// HSB: saturation up by (1 − shade)·k, brightness × shade. The reference did\n// this on pow(albedo, 2.2) and wrote pow(1/2.2) — kept verbatim: that chain is\n// the mat's colour on screen.\nfn shade_mat(u: MatUniforms, albedo: vec3f, gobo: f32) -> vec3f {\n  // Lit: shade is exactly 1, the saturation bump exactly 0, and the chain is\n  // pow(pow(albedo, 2.2), 1/2.2) — the identity. Every pixel outside the\n  // cone, and every lit one inside it, skips six pows and the HSB round trip.\n  if (gobo >= 1.0) { return albedo; }\n  let shade = mix(1.0, u.gobo.w + (1.0 - u.gobo.w) * gobo, u.gobo.z);\n  var hsb = rgb2hsb(pow(albedo, vec3f(2.2)));\n  hsb.y = min(hsb.y + (1.0 - shade) * u.grade.x, 1.0);\n  hsb.z = hsb.z * shade;\n  return pow(hsb2rgb(hsb), vec3f(1.0 / 2.2));\n}\n\n// ---- the NIGHT (MAT.md; src/mat/night.ts is the same arithmetic on the CPU):\n// the Moon in place of the Sun, and the eye that sees by it. The day's chain\n// above is untouched — `mat_colour` returns it, alone, when `night.x` is 0.\nfn night_luminance(c: vec3f) -> f32 { return dot(c, vec3f(0.2126729, 0.7151522, 0.0721750)); }\n\n// Scotopic luminance V' from XYZ — Larson, Rushmeier & Piatko 1997's regression:\n// the rods peak at 507 nm, so greens and blues keep their brightness by night and reds die.\nfn night_scotopic(c: vec3f) -> f32 {\n  let X = dot(c, vec3f(0.4124564, 0.3575761, 0.1804375));\n  let Y = dot(c, vec3f(0.2126729, 0.7151522, 0.0721750));\n  let Z = dot(c, vec3f(0.0193339, 0.1191920, 0.9503041));\n  return Y * (1.33 * (1.0 + (Y + Z) / max(X, 1e-6)) - 1.68);\n}\n\n// CIE 191:2010's mesopic weight — the cones' share of the seeing at L cd/m²:\n// 0 at 0.005 (the rods alone), 1 at 5 (the cones alone).\nfn night_mesopic(L: f32) -> f32 { return saturate(0.767 + 0.3334 * log(max(L, 1e-9)) * 0.4342944819); }\n\nfn night_encode(c: vec3f) -> vec3f {\n  return mix(c * 12.92, 1.055 * pow(max(c, vec3f(0.0)), vec3f(1.0 / 2.4)) - 0.055, step(vec3f(0.0031308), c));\n}\n\nfn night_mat(u: MatUniforms, albedo: vec3f, gobo: f32, noise: f32) -> vec3f {\n  let shade = u.moon.w + (1.0 - u.moon.w) * gobo;                         // the Moon, and the sky's share where it is blocked\n  let cone = albedo * u.moon.xyz * shade;                                  // the mat under the Moon, as the partly adapted cones take it\n  let rod = max(night_scotopic(cone), 0.0) / night_scotopic(vec3f(1.0));  // the rods' signal, white = 1\n  let L = u.night.y * night_luminance(cone) * 0.3183098862;               // cd/m² on the desk: E · ρ / π\n  let see = mix(rod * u.rod.xyz, cone, night_mesopic(L));                 // what the eye reports\n  let disp = u.eigengrau.xyz + see * u.night.z;                            // the dark's own grey under it, at the appearance's scale\n  return night_encode(disp) + (noise - 0.5) * u.night.w;                   // encoded; then the rods' own noise\n}\n\n// The mat's colour on screen: the day's chain, the night, or a cross-fade of the two.\nfn mat_colour(u: MatUniforms, albedo: vec3f, gobo: f32, noise: f32) -> vec3f {\n  if (u.night.x <= 0.0) { return shade_mat(u, albedo, gobo); }\n  let night = night_mat(u, albedo, gobo, noise);\n  if (u.night.x >= 1.0) { return night; }\n  return mix(shade_mat(u, albedo, gobo), night, u.night.x);\n}\n",
  "packs/mat/wind.wgsl": "// The wind pass — the reference's `goboWind`: one fragment per plate texel,\n// R silhouette + three sines whose amplitudes and phase the plate's other\n// channels carry, written to an r8 target the mat pass samples. Runs only when\n// the gobo time moved; the target is 512² like the plate.\n\n@group(0) @binding(0) var<uniform> u: MatUniforms;\n@group(0) @binding(1) var plate: texture_2d<f32>;\n\nstruct VSOut { @builtin(position) clip: vec4f }\n\n@vertex\nfn vs(@builtin(vertex_index) vid: u32) -> VSOut {\n  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));\n  var out: VSOut;\n  out.clip = vec4f(p[vid], 0.0, 1.0);\n  return out;\n}\n\n@fragment\nfn fs(in: VSOut) -> @location(0) vec4f {\n  let params = textureLoad(plate, vec2i(in.clip.xy), 0);\n  let time = u.wind.x;\n  let strength = u.wind.y;\n  let s = params.r;\n  let amp1 = params.g * strength;\n  let phase1 = (params.b - 0.5) * 6.283185;\n  let amp23 = params.a * strength;\n  let waves = sin(time * vec3f(1.0, 2.0, 3.0) + phase1 * vec3f(1.0, 2.0, 0.5));\n  let motion = (amp1 * waves.x) + (amp23 * 0.5 * waves.y) + (amp23 * 0.3 * waves.z);\n  let v = clamp(s + motion, 0.0, 1.0);\n  return vec4f(v, 0.0, 0.0, 1.0);\n}\n",
  "packs/needle/fine-needle.wgsl": "// PASS 2, dense branch — the FINE rung as one fullscreen triangle, NEEDLE glyph.\n// Same switch-over rule as fine-dot; a separate entry so neither glyph's code\n// is ever compiled into the other's pipeline.\n\n@group(0) @binding(0) var<uniform> u: Uniforms;\n@group(0) @binding(1) var atlas_tex: texture_2d<f32>;\n\nstruct VSOut { @builtin(position) clip: vec4f }\n\n@vertex\nfn vs(@builtin(vertex_index) vid: u32) -> VSOut {\n  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));\n  var out: VSOut;\n  out.clip = vec4f(p[vid], 0.0, 1.0);\n  return out;\n}\n\n@fragment\nfn fs(in: VSOut) -> @location(0) vec4f {\n  let screen = in.clip.xy / dpr(u);\n  let spacing = u.rungs.x;\n  let world = u.phase.xy + screen / zoom(u);\n  let idx = round(world / spacing);\n  if (promoted(idx)) { discard; }\n\n  let site = site_screen(u, idx * spacing);\n  let cell = max(spacing * zoom(u), 1e-6);\n  let hl = fit_hl(u, cell);\n  let hw = fit_hw(u, cell);\n  let aa = aa_px(u);\n  if (length(screen - site) > needle_len(u, hl) + aa * 2.0) { discard; }\n\n  let packed = field_at_site(u, atlas_tex, atlas_index(u, idx, spacing), site);\n  if (packed.z < -0.5) { discard; }\n\n  let mag = length(packed.xy);\n  let influence = saturate(mag);\n  let dir = needle_dir(u, packed.xy);\n  let len = needle_len(u, mix(hl * 0.55, hl, influence));\n  let wid = needle_wid(u, mix(hw * 0.85, hw * 1.15, influence));\n  let a = cover_needle(screen, site, dir, len, wid, aa) * portal_cover(screen, u.portals, u.clips, dpr(u)) *\n          mix(0.35, 1.0, influence) * rung_alpha(u, 0.0) * u.color.w;\n  if (a < 0.004) { discard; }\n  return vec4f(u.color.xyz, a);\n}\n",
  "packs/needle/glyph-needle.wgsl": "// PASS 2 — instanced NEEDLE glyphs. Same schedule as the dot entry; the glyph\n// is a rotated capsule that orients along the field instead of a disc that\n// swells with it. RUNG is a pipeline override: 0 fine, 1 mid, 2 coarse.\n// Needle has its own entry: nothing here knows a dot exists.\n\noverride RUNG: f32 = 1.0;\n\n@group(0) @binding(0) var<uniform> u: Uniforms;\n@group(0) @binding(1) var atlas_tex: texture_2d<f32>;\n\nstruct VSOut {\n  @builtin(position) clip: vec4f,\n  @location(0) @interpolate(flat) site: vec2f,\n  @location(1) @interpolate(flat) dir: vec2f,\n  @location(2) @interpolate(flat) extent: vec2f,   // half length, half width\n  @location(3) @interpolate(flat) alpha: f32,\n}\n\nconst CORNERS = array<vec2f, 6>(\n  vec2f(-1.0, -1.0), vec2f(1.0, -1.0), vec2f(1.0, 1.0),\n  vec2f(-1.0, -1.0), vec2f(1.0, 1.0), vec2f(-1.0, 1.0),\n);\n\n@vertex\nfn vs(@builtin(vertex_index) vid: u32, @builtin(instance_index) iid: u32) -> VSOut {\n  var out: VSOut;\n  out.clip = vec4f(2.0, 2.0, 2.0, 1.0);\n  out.site = vec2f(0.0);\n  out.dir = vec2f(0.0, 1.0);\n  out.extent = vec2f(0.0);\n  out.alpha = 0.0;\n\n  let spacing = rung_spacing(u, RUNG);\n  let cell = max(spacing * zoom(u), 1e-6);\n  let cols = max(u32(select(select(u.cols.x, u.cols.y, RUNG > 0.5), u.cols.z, RUNG > 1.5) + 0.5), 1u);\n  // The slot's box (PORTAL.md §2.3): the instance grid starts at the box's top-left (a root's is 0 — exactly the phase)\n  let origin = floor((u.phase.xy + u.box.xy / zoom(u)) / spacing) - vec2f(1.0);\n  let idx = origin + vec2f(f32(iid % cols), f32(iid / cols));\n\n  if (RUNG < 1.5 && promoted(idx)) { return out; }\n\n  let site = site_screen(u, idx * spacing);\n  let hl = fit_hl(u, cell);\n  let hw = fit_hw(u, cell);\n  let aa = aa_px(u);\n  let extent = needle_len(u, hl) + aa * 2.0;\n  if (site.x < u.box.x - extent || site.y < u.box.y - extent ||\n      site.x > u.box.x + u.box.z + extent || site.y > u.box.y + u.box.w + extent) { return out; }\n\n  let packed = field_at_site(u, atlas_tex, atlas_index(u, idx, spacing), site);\n  if (packed.z < -0.5) { return out; }\n\n  let mag = length(packed.xy);\n  let influence = saturate(mag);\n  let dir = needle_dir(u, packed.xy);\n  let len = needle_len(u, mix(hl * 0.55, hl, influence));\n  let wid = needle_wid(u, mix(hw * 0.85, hw * 1.15, influence));\n  let alpha = mix(0.35, 1.0, influence) * rung_alpha(u, RUNG) * u.color.w;\n  if (alpha < 0.004) { return out; }\n\n  // Axis-aligned quad large enough to hold the rotated capsule, so the fragment\n  // stage can do the exact coverage test the fullscreen reference does.\n  let corner = CORNERS[vid];\n  let pos = site + corner * (len + aa * 2.0);\n  out.clip = vec4f(pos.x / u.view.x * 2.0 - 1.0, 1.0 - pos.y / u.view.y * 2.0, 0.0, 1.0);\n  out.site = site;\n  out.dir = dir;\n  out.extent = vec2f(len, wid);\n  out.alpha = alpha;\n  return out;\n}\n\n@fragment\nfn fs(in: VSOut) -> @location(0) vec4f {\n  let screen = in.clip.xy / dpr(u);\n  let a = in.alpha *\n    cover_needle(screen, in.site, in.dir, in.extent.x, in.extent.y, aa_px(u)) * portal_cover(screen, u.portals, u.clips, dpr(u));\n  if (a < 0.004) { discard; }\n  return vec4f(u.color.xyz, a);\n}\n",
  "packs/vf-frame/frame.wgsl": "// VibeField's card frame — a CARD PROGRAM pack (design-014): the composed\n// corners with their bays, the close and lock buttons with their glyphs, the\n// §7 selection ring, the §2.3 hairline and the §7 overlap heat, on the engine's\n// record HEAD plus this pack's TAIL. A PURE module: the record, the pass\n// uniforms and the pixel scale are parameters. Every geometric number was\n// resolved on the CPU this frame (choreography.ts) — no curve is evaluated\n// here — and every colour comes in through the uniform slots this pack fills\n// from its theme section: this file names no colour. (Lineage: research/\n// sdf-card/src/sdf/card.wgsl, glyphs.wgsl and render.wgsl; the engine's\n// frame.wgsl before design-014 split the seam.)\n//\n//   frame = outer \\ inner\n//   outer = rounded rect\n//   inner = rounded rect with a rounded-rect NOTCH cut flush into each corner\n//\n// The TAIL (packs/vf-frame/index.ts packs it): ext[0..5] nw · nh · rho · rfH ·\n// rfV · baseR (per corner, TL TR BR BL); ext[6] closeC.xy · closeR · closeGlyphW;\n// ext[7] lockC.xy · lockR · lockGlyphScale; ext[8] closeGlyphR · lockOpen ·\n// lockSquash · hoverC; ext[9] hoverK. The UNIFORM slots: uext[0] colFrame ·\n// [1] colBtn · [2] colBtnHover · [3] colDestructive · [4] colInk · [5]\n// colInkStrong · [6] colInkMuted · [7] colOnSolid · [8] colGlow · [9] colRim ·\n// [10] glowK (height, alpha reject, alpha accept) · [11] rimK (width, alpha\n// reject, alpha accept).\n\nfn vf_nw(G: Frame) -> vec4f { return G.ext[0]; }\nfn vf_nh(G: Frame) -> vec4f { return G.ext[1]; }\nfn vf_rho(G: Frame) -> vec4f { return G.ext[2]; }\nfn vf_rfH(G: Frame) -> vec4f { return G.ext[3]; }\nfn vf_rfV(G: Frame) -> vec4f { return G.ext[4]; }\nfn vf_baseR(G: Frame) -> vec4f { return G.ext[5]; }\n\n// One-hot corner mask, TL TR BR BL, from the sign of p.\nfn corner_mask(p: vec2f) -> vec4f {\n  let a = select(0.0, 1.0, p.x >= 0.0);\n  let b = select(0.0, 1.0, p.y >= 0.0);\n  return vec4f((1.0 - a) * (1.0 - b), a * (1.0 - b), a * b, (1.0 - a) * b);\n}\n\n// One corner's constraint region: the quadrant that corner owns, minus its\n// notch. Every rounding joins two PERPENDICULAR half-planes, the condition\n// under which the fillet operators are exact rather than plausible.\nfn corner_sd(p: vec2f, ih: vec2f, s: vec2f,\n             nw: f32, nh: f32, rho: f32, rfH: f32, rfV: f32, br: f32) -> f32 {\n  let u  = p * s;\n  let bx = u.x - ih.x;\n  let by = u.y - ih.y;\n  let dR = op_isect_round(bx, by, br);         // the card's own rounded corner\n  if (nw <= 0.001 || nh <= 0.001) { return dR; }\n  let nx = u.x - (ih.x - nw);\n  let ny = u.y - (ih.y - nh);\n  let dN = op_isect_round(-nx, -ny, rho);      // the notch, concave corner rounded by rho\n  // The content is the ROUNDED card with the notch cut from it. While the\n  // notch is smaller than the corner's own arc it bites nothing — the arc\n  // lies outside it — so the bay blooms out of the rounded corner instead of\n  // out of a square one; fully revealed, the notch contains the arc and the\n  // intersection is the notched card exactly.\n  // INSIDE: the intersection form — max is exact inside.\n  let din = max(max(op_isect_round(by, -dN, rfH),\n                    op_isect_round(bx, -dN, rfV)), dR);\n  if (din <= 0.0) { return din; }\n  // OUTSIDE: the same region as a union of two rounded quadrants — min is\n  // exact outside. Both forms share the zero set, so switching on the sign is seamless.\n  let f1 = op_isect_round(by, nx, rfH);\n  let f2 = op_isect_round(bx, ny, rfV);\n  return max(op_union_round(f1, f2, rho), dR);\n}\n\nfn frame_inner(G: Frame, pw: vec2f, exact: bool) -> f32 {\n  let p  = pw - G.centre;\n  let ih = G.ih;\n  let nw = vf_nw(G);\n  let nh = vf_nh(G);\n  let rho = vf_rho(G);\n  let rfH = vf_rfH(G);\n  let rfV = vf_rfV(G);\n  let baseR = vf_baseR(G);\n  if (exact) {\n    // Intersect all four corner regions: a real distance field over the whole plane.\n    var d =    corner_sd(p, ih, vec2f(-1.0, -1.0), nw.x, nh.x, rho.x, rfH.x, rfV.x, baseR.x);\n    d = max(d, corner_sd(p, ih, vec2f( 1.0, -1.0), nw.y, nh.y, rho.y, rfH.y, rfV.y, baseR.y));\n    d = max(d, corner_sd(p, ih, vec2f( 1.0,  1.0), nw.z, nh.z, rho.z, rfH.z, rfV.z, baseR.z));\n    d = max(d, corner_sd(p, ih, vec2f(-1.0,  1.0), nw.w, nh.w, rho.w, rfH.w, rfV.w, baseR.w));\n    return d;\n  }\n  // FAST: fold by the sign of p and evaluate only the owning corner. Identical\n  // silhouette; exact within min(nw, nh) of the outline, which covers AA, the\n  // border, the shadow and hit-testing.\n  let m = corner_mask(p);\n  let s = vec2f(select(-1.0, 1.0, p.x >= 0.0), select(-1.0, 1.0, p.y >= 0.0));\n  return corner_sd(p, ih, s, dot(nw, m), dot(nh, m), dot(rho, m),\n                   dot(rfH, m), dot(rfV, m), dot(baseR, m));\n}\n\nfn frame_outer(G: Frame, p: vec2f) -> f32 { return sdf_round_box(p - G.centre, G.half, G.outerR); }\n\n// Padlock, in units where the button radius is the design radius. `open` swings\n// the shackle about the base of its LEFT leg; `sq` is squash-and-stretch.\nfn sdf_lock(pp: vec2f, sc: f32, open: f32, sq: f32) -> f32 {\n  let p = pp / sc;\n  let bh   = 9.0 * (1.0 - 0.09 * sq);\n  let bw   = 11.0 * (1.0 + 0.06 * sq);\n  let body = sdf_round_box(p - vec2f(0.0, 4.4 + 9.0 - bh), vec2f(bw, bh), 2.8);\n  let pivot = vec2f(-6.6, -2.0);\n  let a  = -open * 0.50;\n  var q  = p - vec2f(0.0, -2.0 * open) - pivot;\n  let ca = cos(a);\n  let sa = sin(a);\n  q = vec2f(ca * q.x + sa * q.y, -sa * q.x + ca * q.y) + pivot;\n  let arcC = vec2f(0.0, -4.6);\n  let ring = max(abs(length(q - arcC) - 6.6) - 2.2, q.y - arcC.y);\n  let legs = min(sdf_segment(q, vec2f(-6.6, -4.6), vec2f(-6.6, -2.0)),\n                 sdf_segment(q, vec2f( 6.6, -4.6), vec2f( 6.6, -2.0))) - 2.2;\n  return min(body, min(ring, legs)) * sc;\n}\n\n// BELOW the content: the §5 ambient shadow, then the frame's two coverages —\n// the solid-chrome band at cF and the interior at cI, partitioning the pixel.\nfn shade_card(G: Frame, u: FrameUniforms, p: vec2f, px: f32) -> Shade {\n  var s: Shade;\n  let exact = u.view.z > 0.5;\n  let dO = frame_outer(G, p);\n  var acc = vec4f(0.0);\n\n  // §5: the outer silhouette, Gaussian-blurred, cast down by `shadowOffset`.\n  // Only outside the card — what the card covers, the card paints.\n  if (G.shadowSigma > 0.01) {\n    let sh = blur_cov(frame_outer(G, p - vec2f(0.0, G.shadowOffset)), G.shadowSigma)\n           * G.shadowAlpha * u.colBg.w * (1.0 - cov(dO, px));\n    acc = over(vec4f(0.0, 0.0, 0.0, sh), acc);\n  }\n  s.under = acc;\n  s.dO = dO;\n  s.chrome = u.uext[0].rgb;\n  // More than a pixel outside the outer box, nothing but the shadow can paint\n  // (every coverage below is 0 there) — and the shadow skirt is most of the\n  // quad, so the notched inner field is never evaluated for it. Exact, not a\n  // heuristic: cov(d, px) is identically 0 for d ≥ px/2.\n  if (dO > px) { s.dI = dO; s.cF = 0.0; s.cI = 0.0; s.skip = true; return s; }\n\n  let dI = frame_inner(G, p, exact);\n  let dF = max(dO, -dI);\n\n  // Frame and content are ADDITIVE, not sequential: their coverages partition\n  // the pixel (cov(dF) + cov(dI) == 1 across the shared boundary), and a second\n  // `over` would leak bg·cF·cI at the seam. Clamped so a rounding slip cannot\n  // push the sum past 1.\n  let cF = cov(dF, px);\n  let cI = min(cov(dI, px), 1.0 - cF);\n  s.dI = dI;\n  s.cF = cF;\n  s.cI = cI;\n  s.skip = false;\n  return s;\n}\n\n// ABOVE the content: the §2.3 hairline · the §7 overlap glow and rim · the §7\n// selection ring · the two buttons.\nfn shade_over(G: Frame, u: FrameUniforms, p: vec2f, px: f32, s: Shade, acc_in: vec4f) -> vec4f {\n  var acc = acc_in;\n  let dO = s.dO;\n  let cF = s.cF;\n  let cI = s.cI;\n  let e8 = G.ext[8];\n  let e9 = G.ext[9];\n  let hoverC = e8.w;\n  let hoverK = e9.x;\n\n  // §2.3 the hairline, 1 px inside the outer edge — the `0 0 0 1px` ring of the\n  // card shadow recipe. §7 the sole-selection ring, 1.5 px inside the same edge,\n  // arriving with the reveal.\n  acc = over(layer(u.colHair, inside_line(dO, u.lines.x, px)), acc);\n\n  // §7 the overlap HEAT (GLOW.md): the LIFTED card is an emitting surface floating\n  // `glowK.x` above this one, and this card receives its light through the SOURCE's own\n  // distance field — the half-plane irradiance ½(1 − d/√(d² + h²)): 1 deep under the\n  // card, ½ at its silhouette, h²/4d² far away; the source's rounded corners follow its\n  // field. Light ADDS (the receiver brightens, never greys), masked to this card's\n  // coverage, between the hairline (beneath) and the ring (above); the rim is the ring's\n  // own line catching the same light. Per instance: a cold card pays one compare.\n  if (G.hot.z > 0.001) {\n    let glowK = u.uext[10];\n    let rimK = u.uext[11];\n    let tier = G.hot.w;\n    let dS = sdf_round_box(p - G.hot.xy, G.src.xy, G.src.z);\n    let h = max(glowK.x, 1e-3);\n    let lit = 0.5 * (1.0 - dS * inverseSqrt(dS * dS + h * h)) * G.hot.z;\n    let glow = u.uext[8].rgb * (mix(glowK.y, glowK.z, tier) * lit * (cF + cI));\n    let rim = u.uext[9].rgb * (mix(rimK.y, rimK.z, tier) * lit * inside_line(dO, rimK.x, px));\n    acc = vec4f(acc.rgb + glow + rim, acc.a);\n  }\n\n  acc = over(layer(vec4f(u.colRing.rgb, G.ring), inside_line(dO, u.lines.y, px)), acc);\n\n  // The lock: a §7 fill that steps on hover; the glyph wears the text ramp —\n  // secondary locked, tertiary open, foreground on hover.\n  let lock = G.ext[7];\n  if (lock.z > 0.05) {\n    let lp = p - lock.xy;\n    let cB = cov(sdf_circle(lp, lock.z), px);\n    acc = over(layer(mix(u.uext[1], u.uext[2], hoverK), cB), acc);\n    let ink = mix(mix(u.uext[4], u.uext[6], e8.y), u.uext[5], hoverK);\n    acc = over(layer(ink, cov(sdf_lock(lp, lock.w, e8.y, e8.z), px)), acc);\n  }\n  // The close: colourless at rest like every other chrome; §2.5 red the moment\n  // it is armed — destructive is visually distinct BEFORE the act.\n  let close = G.ext[6];\n  if (close.z > 0.05) {\n    let bp = p - close.xy;\n    let cB = cov(sdf_circle(bp, close.z), px);\n    acc = over(layer(u.uext[1], cB), acc);\n    acc = over(layer(vec4f(u.uext[3].rgb, hoverC), cB), acc);\n    let ink = mix(u.uext[4], u.uext[7], hoverC);\n    acc = over(layer(ink, cov(sdf_rounded_x(bp, close.w, e8.x), px)), acc);\n  }\n  return acc;\n}\n",
  "portal-fill.wgsl": "// The portal FILL — the canvas background through the portal, drawn before a\n// portal-clipped slot's grid and frames so that slot is OPAQUE inside its\n// portal: the two frames of a flight tile the screen (the arriving one on the\n// card face, the departed one around it) instead of superimposing their\n// grids. One fullscreen triangle, straight alpha = opacity × coverage through\n// the chain — the slot's own face grown by `bg.w` device px for a slot drawn\n// beneath a HOLE, so the hole's edge partitions with the plate around it and\n// nothing under the container ever shows (PORTAL.md §10).\n\n@group(0) @binding(0) var<uniform> u: FillUniforms;\n\nstruct VSOut { @builtin(position) clip: vec4f }\n\n@vertex\nfn vs(@builtin(vertex_index) vid: u32) -> VSOut {\n  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));\n  var out: VSOut;\n  out.clip = vec4f(p[vid], 0.0, 1.0);\n  return out;\n}\n\n@fragment\nfn fs(in: VSOut) -> @location(0) vec4f {\n  let dpr = max(u.view.z, 1.0);\n  let a = u.view.w * portal_cover_grown(in.clip.xy / dpr, u.portals, u.clips, dpr, u.bg.w);\n  if (a < 0.002) { discard; }\n  return vec4f(u.bg.xyz, a);\n}\n",
  "portal.wgsl": "// The portal clip — a slot's ground and frames are visible only through a\n// rounded rect on screen (CSS px): its FACE and, for a nested slot, every face\n// above it — the CHAIN (src/nav/portal.ts `Presentation`, `within`). A PURE\n// module every pass includes: the records arrive as parameters. `clips[i].y`\n// < 0.5 ends the chain (an empty chain is no clip at all, and the loop is one\n// compare); `clips[i].x` is a face's corner radius.\n\n// = nav/portal.ts PORTAL_CHAIN, the uniform arrays' length; a mismatch fails to compile.\nconst PORTAL_CHAIN = 6u;\n\nfn portal_sd(p: vec2f, half: vec2f, r: f32) -> f32 {\n  let rr = min(r, min(half.x, half.y));\n  let q = abs(p) - half + vec2f(rr, rr);\n  return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0) - rr;\n}\n\n// Coverage at a CSS-px point through ONE face grown by `grow` device px: 1 inside, 0 outside, a one-device-px ramp across the edge.\nfn portal_cover_one(p_css: vec2f, portal: vec4f, clip: vec4f, dpr: f32, grow: f32) -> f32 {\n  let px = 1.0 / max(dpr, 1.0);\n  let d = portal_sd(p_css - portal.xy, portal.zw, clip.x) - grow * px;\n  return clamp(0.5 - d / px, 0.0, 1.0);\n}\n\n// Coverage through the chain: the slot's own face grown by `grow` device px (the fill's one\n// px, so the hole's edge partitions with the plate — PORTAL.md §10) times every face above\n// it as it is. The product: a nested slot shows only where all of them agree.\nfn portal_cover_grown(p_css: vec2f, portals: array<vec4f, PORTAL_CHAIN>, clips: array<vec4f, PORTAL_CHAIN>, dpr: f32, grow: f32) -> f32 {\n  var c = 1.0;\n  for (var i = 0u; i < PORTAL_CHAIN; i++) {\n    if (clips[i].y < 0.5) { break; }\n    c *= portal_cover_one(p_css, portals[i], clips[i], dpr, select(0.0, grow, i == 0u));\n  }\n  return c;\n}\n\nfn portal_cover(p_css: vec2f, portals: array<vec4f, PORTAL_CHAIN>, clips: array<vec4f, PORTAL_CHAIN>, dpr: f32) -> f32 {\n  return portal_cover_grown(p_css, portals, clips, dpr, 0.0);\n}\n",
} as const;
export type WgslFile = keyof typeof WGSL;
